"""The group generated by the mother and father moves, and the family's spectrum."""
import numpy as np
from torus_count.explore import adjacency, ramanujan


def generate(gens, limit=200000):
    n = len(gens[0]); ident = tuple(range(n)); seen = {ident}; frontier = [ident]
    while frontier:
        nxt = []
        for g in frontier:
            for h in gens:
                x = tuple(h[i] for i in g)
                if x not in seen:
                    seen.add(x); nxt.append(x)
                    if len(seen) > limit:
                        return None
        frontier = nxt
    return seen


def group_profile(plus, minus):
    """Order of the group generated by the mother and father moves, restricted to the even
    words (two steps: back to the same dual set), and whether it is abelian."""
    n = len(plus); m = n // 2
    P, M = tuple(plus), tuple(minus)
    comp = lambda f, g: tuple(f[g[i]] for i in range(n))
    two = [comp(P, P), comp(P, M), comp(M, P), comp(M, M)]          # two-generation moves
    G = generate(two)
    if G is None:
        return None, None
    ab = all(comp(a, b) == comp(b, a) for a in two for b in two)
    # restrict to one dual set: number of distinct actions on the A tori
    onA = {tuple(g[i] for i in range(n) if True) for g in G}
    return len(G), ab


def grandchild_network(plus, minus):
    """T on the A tori: each torus -> its four grandchildren (mother's mother-child, etc.).
    The family's eigenvalues are the square roots of T's eigenvalues."""
    n = len(plus); m = n // 2
    T = np.zeros((m, m), dtype=int)
    for a in range(m):
        for c1 in (plus[a], minus[a]):
            for c2 in (plus[c1], minus[c1]):
                T[a, c2] += 1
    return T


def repeated_grandchildren(plus, minus):
    """How many of the 4m grandchild paths duplicate another path's endpoint."""
    T = grandchild_network(plus, minus)
    return int((T * (T - 1) // 2).sum()), int((T >= 2).sum())


def first_reconvergence(plus, minus, maxdepth=8):
    """Smallest r such that some torus reaches some descendant r generations down by two
    different routes (two different mother/father sequences). Larger = lineages stay distinct
    longer."""
    n = len(plus)
    for r in range(1, maxdepth + 1):
        for s in range(n):
            ends = {}
            frontier = [(s, ())]
            for _ in range(r):
                frontier = [(c, path + (t,)) for v, path in frontier for t, c in ((0, plus[v]), (1, minus[v]))]
            for v, path in frontier:
                if v in ends:
                    return r
                ends[v] = path
    return maxdepth + 1
